No existing code found. Here's a debounce solution for React:

```jsx
// Custom hook
function useDebounce(value, delay) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(handler);
  }, [value, delay]);

  return debouncedValue;
}

// In your component
function SearchInput() {
  const [query, setQuery] = useState('');
  const debouncedQuery = useDebounce(query, 300);

  useEffect(() => {
    if (debouncedQuery) {
      // API call fires here, not on every keystroke
      fetch(`/api/search?q=${debouncedQuery}`)
        .then(res => res.json())
        .then(data => setResults(data));
    }
  }, [debouncedQuery]);

  return <input value={query} onChange={e => setQuery(e.target.value)} />;
}
```

**Alternative: Direct debounce on handler** (simpler if no intermediate state needed)
```jsx
function SearchInput() {
  const [results, setResults] = useState([]);
  const timeoutRef = useRef(null);

  const handleSearch = (query) => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => {
      fetch(`/api/search?q=${query}`)
        .then(res => res.json())
        .then(data => setResults(data));
    }, 300);
  };

  return <input onChange={e => handleSearch(e.target.value)} />;
}
```

Pick the first if you need the debounced value elsewhere; the second if you just want to delay the side effect. Replace `300` (milliseconds) with your preferred delay.
